  "ref_date_used": "2023-10-25",
  "claims": [
    {
      "kind": "conclusion",
      "text": "\"159. Provisional attachment of property .-(1) Where the Commissioner decides to attach any property, including bank account in accordance with the provisions of section 83, he shall pass an order in FORM GST DRC -22 to that effect mentioning therein, the details of property which is attached.\"",
      "citation_ids": [
        "CGST/r159@v2"
      ]
    },
    {
      "kind": "conclusion",
      "text": "\"The Commissioner shall send a in FORM GST DRC-22 to the concerned Revenue Authority or Transport Authority or any such Authority to place encumbrance on the said movable or immovable property, which shall be removed only on the written instructions from the Commissioner to that effect.\"",
      "citation_ids": [
        "CGST/r159@v2"
      ]
    },
    {
      "kind": "conclusion",
      "text": "\"Where the property attached is of perishable or hazardous nature, and if the taxable person pays an amount equivalent to the market price of such property or the amount that is or may become payable by the taxable person, whichever is lower, then such property shall be released forthwith, by an order in FORM GST DRC-23, on proof of payment.\"",
      "citation_ids": [
        "CGST/r159@v2"
      ]
    },
    {
      "kind": "conclusion",
      "text": "\"Where the taxable person fails to pay the amount referred to in sub-rule (3) in respect of the said property of pe rishable or hazardous nature, the Commissioner may dispose of such property and the amount realized thereby shall be adjusted against the tax, interest, penalty, fee or any other amount payable by the taxable person.\"",
      "citation_ids": [
        "CGST/r159@v2"
      ]
    },
    {
      "kind": "conclusion",
      "text": "\"Any person whose property is attach ed may, within seven days of the attachment under sub-rule (1), file an objection to the effect that the property attached was or is not liable to attachment, and the Commissioner may, after affording an opportunity of being heard to the person filing the objection, release the said property by an order in FORM GST DRC- 23.\"",
      "citation_ids": [
        "CGST/r159@v2"
      ]
    },
    {
      "kind": "conclusion",
      "text": "\"The Commissioner may, upon being satisfied that the property was, or is no longer liable for attachment, release such property by issuing an order in FORM GST DRC- 23.\"",
      "citation_ids": [
        "CGST/r159@v2"
      ]
    }
  ],
  "assumptions": []
}

